    make(3, "化學電池中的電解質主要負責什麼功能？", {"A": "讓離子在電池內部移動，協助完成內部電路與電荷平衡", "B": "只把所有電子鎖在負極，完全不讓離子移動", "C": "取代外部導線把燈泡直接點亮", "D": "把電池化學能全部轉成聲能"}, "A", "電解質提供離子移動的環境，使氧化還原反應能持續並維持電荷平衡；電子主要走外部導線，選 A。", "判斷電解質的角色時，先區分內部離子通道與外部電子通道。", ["找出電池內部與外部各自的傳輸位置。", "外部金屬線主要傳遞電子。", "電解質提供離子移動的路徑。", "離子移動可避免局部電荷持續累積。", "因此選 A。"], "medium"),
    make(4, "兩個規格相同的 1.5 V 電池以相同方向串聯，理想情況下燈泡兩端可得到約多少電壓？", {"A": "0 V", "B": "0.75 V", "C": "1.5 V", "D": "3.0 V"}, "D", "相同方向串聯時，兩個電池的電位差相加，1.5 V＋1.5 V＝3.0 V，選 D。", "先畫出電池方向，再用串聯電壓相加，避免把並聯規則套錯。", ["確認兩顆電池電壓都是 1.5 V。", "確認正負方向相同而不是相反串接。", "串聯表示電位差沿同一路徑累加。", "計算 1.5＋1.5＝3.0 V。", "所以選 D。"], "easy"),
    make(5, "兩個規格相同、電量狀態相近的電池以相同方向並聯，通常最合理的描述是？", {"A": "端電壓大約仍等於單顆電池，但可提高供電持續性；須先確認電池適合並聯", "B": "端電壓必定加倍且不需考慮規格", "C": "端電壓一定變成零", "D": "並聯會讓電子停止移動"}, "A", "相同電池並聯時端電壓通常不相加，並可增加可供電量或電流能力；不同狀態電池不可任意並聯，選 A。", "先分辨串聯／並聯的電壓規則，再補上實際使用的相容性限制。", ["確認兩顆電池規格與電量狀態相近。", "並聯把同名端接在一起。", "理想端電壓仍約為單顆電池電壓。", "可增加供電持續時間或瞬間供電能力。", "因此選 A，並記得不可任意混接。"], "hard"),
